import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CoverFlowCarouselProps = Record<string, any>;

const CoverFlowCarousel: React.FC<CoverFlowCarouselProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  images = [
    "https://www.pexels.com/photo/girl-taking-photo-1493111/",
    "https://www.pexels.com/photo/notebooks-on-the-table-5717455/",
    "https://www.pexels.com/photo/clothes-hanger-hanged-on-clothes-rack-1148960/",
    "https://www.pexels.com/photo/woman-holding-a-make-up-brush-and-mirror-8956121/"
  ],
  perspective = 1200,
  spacing = 450,
  rotationAngle = 45,
  scaleFactor = 0.6,
}) => {
  // Use a stable dummy font to satisfy the loader pattern requirement
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Normalize images input: Supports both Pexels URLs (auto-upgrade) and direct uploads (raw string)
  const processedImages = React.useMemo(() => {
    return images.map(url => {
      // Check if it's a Pexels URL to upgrade quality
      const match = url.match(/\/photo\/[a-z0-9-]+-(\d+)\/?/i) || url.match(/\/(\d+)\/?$/);
      if (match && match[1]) {
        return `https://images.pexels.com/photos/${match[1]}/pexels-photo-${match[1]}.jpeg?auto=compress&cs=tinysrgb&w=3840`;
      }
      // Return raw URL for uploaded files or other sources
      return url;
    });
  }, [images]);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate the current scroll position so it fits exactly within durationInSeconds
  // We want to go from index 0 to index (length - 1) over the course of the video
  const progress = frame / (durationInFrames - 1);
  const currentScrollIndex = interpolate(
    progress, 
    [0, 1], 
    [0, Math.max(0, processedImages.length - 1)]
  );

  // Constants for layout
  const cardWidth = width * 0.3;
  const cardHeight = cardWidth * 1.5; // Aspect ratio
  const centerY = height / 2 - cardHeight / 2;
  const centerX = width / 2 - cardWidth / 2;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: `${perspective}px`,
        overflow: "hidden",
        fontFamily: "Inter",
      }}
    >
      <AbsoluteFill
        style={{
          transformStyle: "preserve-3d",
        }}
      >
        {processedImages.map((src, i) => {
          // Calculate distance from current focus
          const distance = i - currentScrollIndex;

          // Interpolate properties based on distance
          
          // X Position: Center is 0. Left is negative spacing. Right is positive spacing.
          const xVal = interpolate(
            distance,
            [-2, -1, 0, 1, 2],
            [-spacing * 1.6, -spacing, 0, spacing, spacing * 1.6],
            { extrapolateLeft: "extend", extrapolateRight: "extend" }
          );

          // Z Position: Center is 0 (forward). Sides are pushed back.
          const zVal = interpolate(
            Math.abs(distance),
            [0, 1],
            [0, -400],
            { extrapolateRight: "clamp" }
          );

          // Rotation Y
          const rotateYVal = interpolate(
             distance,
             [-1, 0, 1],
             [rotationAngle, 0, -rotationAngle],
             { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Scale: Center is 1, sides scale down to scaleFactor
          const scaleVal = interpolate(
            Math.abs(distance),
            [0, 1],
            [1, scaleFactor],
            { extrapolateRight: "clamp" }
          );

          // Opacity/Dimming for depth effect
          const opacity = interpolate(
            Math.abs(distance),
            [0, 2.5],
            [1, 0.3],
            { extrapolateRight: "clamp" }
          );

          // Z-Index calculation: Closer items must be on top
          const zIndex = Math.round(1000 - Math.abs(distance) * 100);

          return (
            <AbsoluteFill
              key={i}
              style={{
                width: cardWidth,
                height: cardHeight,
                left: centerX,
                top: centerY,
                transformStyle: "preserve-3d",
                transform: `translateX(${xVal}px) translateZ(${zVal}px) rotateY(${rotateYVal}deg) scale(${scaleVal})`,
                zIndex,
                opacity,
                transition: "none", 
              }}
            >
              {/* Main Image Card */}
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: 15,
                  overflow: "hidden",
                  boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
                  backgroundColor: "#222",
                  border: "2px solid rgba(255,255,255,0.1)",
                }}
              >
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              </div>

              {/* Reflection Effect */}
              <div
                style={{
                  position: "absolute",
                  top: "100%",
                  left: 0,
                  width: "100%",
                  height: "100%",
                  transform: "scaleY(-1) translateY(0px)",
                  opacity: 0.3,
                  maskImage: "linear-gradient(transparent 60%, black 100%)",
                  WebkitMaskImage: "linear-gradient(transparent 60%, black 100%)",
                  pointerEvents: "none",
                }}
              >
                 <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    borderRadius: 15,
                  }}
                />
              </div>
            </AbsoluteFill>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CoverFlowCarousel;